s-saxony" target="_blank" rel="noreferrer">YouTube</a> </div> </div> <div class="footer-bottom"> <span>© 2026 IBS-Saxony UG (haftungsbeschränkt). Alle Rechte vorbehalten.</span> <button class="footer-consent" type="button" onclick="window.dispatchEvent(new Event('ibs-saxony-reset-consent'))">Cookie-Einstellungen ändern</button> </div> </footer>   <?php if ($ibsHasAnalytics): ?>
